namespace ToneCustoms.ShellStudio.Core;
public static class ProjectPaths { public static string AppRoot=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ToneCustoms","ShellStudio");public static string Projects=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"ToneCustoms Shell Studio","Projects");public static string Logs=>Path.Combine(AppRoot,"Logs");public static string Temp=>Path.Combine(AppRoot,"Temp");public static void Ensure(){Directory.CreateDirectory(AppRoot);Directory.CreateDirectory(Projects);Directory.CreateDirectory(Logs);Directory.CreateDirectory(Temp);} }
